defmodule SlaLab.Expressions.RouteKey do
  use Ash.Query.Function, name: :route_key

  def args, do: [[:string, :string]]

  def expression(Ash.DataLayer.Ets, [left, right]) do
    {:ok, Ash.Expr.expr(
      if(is_nil(^left) or is_nil(^right), do: nil, else:
        fragment("route_key(?, ?)", ^left, ^right)
      )
    )}
  end

  def expression(Ash.DataLayer.Simple, [left, right]) do
    {:ok, Ash.Expr.expr(
      if(is_nil(^left) or is_nil(^right), do: nil, else:
        fragment("route_key(?, ?)", ^left, ^right)
      )
    )}
  end

  def expression(_, _), do: :unknown

  def evaluate([left, right]) when is_nil(left) or is_nil(right), do: {:known, nil}
  def evaluate([left, right]) when is_binary(left) and is_binary(right) do
    upper1 = String.upcase(left)
    upper2 = String.upcase(right)
    [a, b] = Enum.sort([upper1, upper2])
    {:known, "#{a}|#{b}"}
  end
  def evaluate(_), do: :unknown
end

defmodule SlaLab.Expressions.RatioBps do
  use Ash.Query.Function, name: :ratio_bps

  def args, do: [[:integer, :integer]]

  def expression(Ash.DataLayer.Ets, [num, den]) do
    {:ok, Ash.Expr.expr(
      if(is_nil(^num) or is_nil(^den) or ^den == 0, do: nil, else:
        fragment("ratio_bps(?, ?)", ^num, ^den)
      )
    )}
  end

  def expression(Ash.DataLayer.Simple, [num, den]) do
    {:ok, Ash.Expr.expr(
      if(is_nil(^num) or is_nil(^den) or ^den == 0, do: nil, else:
        fragment("ratio_bps(?, ?)", ^num, ^den)
      )
    )}
  end

  def expression(_, _), do: :unknown

  def evaluate([num, den]) when is_nil(num) or is_nil(den) or den == 0, do: {:known, nil}
  def evaluate([num, den]) when is_integer(num) and is_integer(den) do
    val = (num * 10_000) / den
    # Round half up towards positive infinity
    # Elixir round(val) rounds to nearest integer, ties away from zero. 
    # For positive numbers, this matches "up" (towards infinity).
    res = round(val)
    clamped = max(0, min(20_000, res))
    {:known, clamped}
  end
  def evaluate(_), do: :unknown
end

defmodule SlaLab.Expressions.PenaltyPoints do
  use Ash.Query.Function, name: :penalty_points

  def args, do: [[:integer, :integer]]
  def returns, do: [:integer]
  def predicate?, do: false

  def evaluate([late_hours, weight]) when is_nil(late_hours) or is_nil(weight), do: {:known, nil}
  def evaluate([late_hours, weight]) when is_integer(late_hours) and is_integer(weight) do
    cond do
      weight < 0 -> {:error, "penalty weight must not be negative"}
      late_hours <= 0 -> {:known, 0}
      late_hours <= 24 -> {:known, late_hours * weight}
      true -> {:known, 24 * weight + (late_hours - 24) * weight * 2}
    end
  end
  def evaluate(_), do: :unknown
end

